CREATE TABLE faultline.source_connections(source_id uuid PRIMARY KEY,workspace_id uuid NOT NULL,config jsonb NOT NULL,config_hash text NOT NULL,secret_id uuid NOT NULL,credential_hint text NOT NULL,revision integer NOT NULL DEFAULT 1,capabilities jsonb,probe_binding_hash text,repository_id bigint,disconnected boolean NOT NULL DEFAULT false,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,source_id),FOREIGN KEY(workspace_id,source_id) REFERENCES faultline.sources(workspace_id,id),FOREIGN KEY(workspace_id,secret_id) REFERENCES faultline.secrets(workspace_id,id));
CREATE TABLE faultline.export_declarations(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,source_id uuid NOT NULL,value jsonb NOT NULL,declaration_hash text NOT NULL,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,source_id,id),FOREIGN KEY(workspace_id,source_id) REFERENCES faultline.source_connections(workspace_id,source_id));
CREATE TABLE faultline.integration_captures(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,case_id uuid NOT NULL,revision_id uuid NOT NULL,source_id uuid NOT NULL,job_id uuid NOT NULL UNIQUE,fence uuid NOT NULL,request_hash text NOT NULL,value jsonb NOT NULL,status text NOT NULL,import_id uuid,error_code text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,case_id,id),FOREIGN KEY(workspace_id,case_id,revision_id) REFERENCES faultline.case_revisions(workspace_id,case_id,id),FOREIGN KEY(workspace_id,case_id,job_id) REFERENCES faultline.jobs(workspace_id,case_id,id),FOREIGN KEY(workspace_id,source_id) REFERENCES faultline.source_connections(workspace_id,source_id),FOREIGN KEY(workspace_id,case_id,import_id) REFERENCES faultline.imports(workspace_id,case_id,id));
CREATE TABLE faultline.integration_capture_artifacts(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,case_id uuid NOT NULL,capture_id uuid NOT NULL,object_key text NOT NULL,sha256 text NOT NULL,size_bytes bigint NOT NULL CHECK(size_bytes>0),kind text NOT NULL,provider_ref jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(workspace_id,case_id,capture_id) REFERENCES faultline.integration_captures(workspace_id,case_id,id));
CREATE TABLE faultline.model_profiles(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,name text NOT NULL,provider text NOT NULL CHECK(provider IN('ollama','openai_compatible')),base_url text NOT NULL,model_name text NOT NULL,secret_id uuid,credential_hint text,profile_hash text NOT NULL,capabilities jsonb,probe_binding_hash text,revision integer NOT NULL DEFAULT 1,deleted boolean NOT NULL DEFAULT false,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,id),FOREIGN KEY(workspace_id,secret_id) REFERENCES faultline.secrets(workspace_id,id));
CREATE TABLE faultline.model_budgets(workspace_id uuid NOT NULL,case_id uuid NOT NULL,revision_id uuid NOT NULL,calls_reserved integer NOT NULL DEFAULT 0,calls_spent integer NOT NULL DEFAULT 0,input_reserved bigint NOT NULL DEFAULT 0,input_spent bigint NOT NULL DEFAULT 0,output_reserved bigint NOT NULL DEFAULT 0,output_spent bigint NOT NULL DEFAULT 0,PRIMARY KEY(workspace_id,case_id,revision_id),CHECK(calls_reserved>=0 AND calls_spent>=0 AND input_reserved>=0 AND input_spent>=0 AND output_reserved>=0 AND output_spent>=0),FOREIGN KEY(workspace_id,case_id,revision_id) REFERENCES faultline.case_revisions(workspace_id,case_id,id));
CREATE TABLE faultline.model_calls(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,case_id uuid NOT NULL,revision_id uuid NOT NULL,profile_id uuid NOT NULL,job_id uuid NOT NULL,fence uuid NOT NULL,operation_id uuid NOT NULL,attempt integer NOT NULL,kind text NOT NULL,input_hash text NOT NULL,evidence_hash text NOT NULL,profile_hash text NOT NULL,schema_hash text NOT NULL,credential_version integer,status text NOT NULL,reserved_input integer NOT NULL,reserved_output integer NOT NULL,reported_input integer,reported_output integer,response_hash text,error_code text,started_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz,UNIQUE(operation_id,attempt),FOREIGN KEY(workspace_id,case_id,job_id) REFERENCES faultline.jobs(workspace_id,case_id,id),FOREIGN KEY(workspace_id,profile_id) REFERENCES faultline.model_profiles(workspace_id,id),FOREIGN KEY(workspace_id,case_id,revision_id) REFERENCES faultline.case_revisions(workspace_id,case_id,id));
CREATE TABLE faultline.model_proposals(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,case_id uuid NOT NULL,revision_id uuid NOT NULL,profile_id uuid NOT NULL,job_id uuid NOT NULL UNIQUE,value jsonb NOT NULL,input_hash text NOT NULL,profile_hash text NOT NULL,evidence_hashes jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,case_id,id),FOREIGN KEY(workspace_id,case_id,job_id) REFERENCES faultline.jobs(workspace_id,case_id,id),FOREIGN KEY(workspace_id,profile_id) REFERENCES faultline.model_profiles(workspace_id,id),FOREIGN KEY(workspace_id,case_id,revision_id) REFERENCES faultline.case_revisions(workspace_id,case_id,id));
CREATE TABLE faultline.provider_operations(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN('source_probe','model_probe')),resource_id uuid NOT NULL,input jsonb NOT NULL,input_hash text NOT NULL,status text NOT NULL CHECK(status IN('queued','running','succeeded','failed','cancel_requested','cancelled')),attempt integer NOT NULL DEFAULT 0,fence uuid,lease_until timestamptz,result jsonb,error_code text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
DO $scope$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['source_connections','export_declarations','integration_captures','integration_capture_artifacts','model_profiles','model_budgets','model_calls','model_proposals','provider_operations'] LOOP
 EXECUTE format('ALTER TABLE faultline.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE faultline.%I FORCE ROW LEVEL SECURITY',t);
 EXECUTE format('CREATE POLICY tenant_scope ON faultline.%I USING(workspace_id::text=current_setting(''faultline.workspace_id'',true)) WITH CHECK(workspace_id::text=current_setting(''faultline.workspace_id'',true))',t);
END LOOP;END $scope$;
CREATE POLICY provider_authority ON faultline.provider_operations TO faultline_authority USING(true) WITH CHECK(true);
GRANT SELECT ON faultline.provider_operations TO faultline_authority;
CREATE OR REPLACE FUNCTION faultline.admit_run_slot() RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,faultline AS $fn$
BEGIN
 PERFORM singleton FROM faultline.installation WHERE singleton FOR UPDATE;
 RETURN ((SELECT count(*) FROM faultline.jobs WHERE status IN('queued','running','cancel_requested'))+(SELECT count(*) FROM faultline.provider_operations WHERE status IN('queued','running','cancel_requested')))<2;
END $fn$;
CREATE FUNCTION faultline.provider_operation_routes() RETURNS TABLE(workspace_id uuid,id uuid) LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,faultline AS $fn$
 SELECT workspace_id,id FROM faultline.provider_operations WHERE status='queued' OR (status IN('running','cancel_requested') AND lease_until<now()) ORDER BY created_at,id LIMIT 20
$fn$;
REVOKE ALL ON FUNCTION faultline.provider_operation_routes() FROM PUBLIC;
ALTER FUNCTION faultline.provider_operation_routes() OWNER TO faultline_authority;
GRANT EXECUTE ON FUNCTION faultline.provider_operation_routes() TO faultline_api;
GRANT SELECT,INSERT ON faultline.source_connections,faultline.export_declarations,faultline.integration_captures,faultline.integration_capture_artifacts,faultline.model_profiles,faultline.model_budgets,faultline.model_calls,faultline.model_proposals,faultline.provider_operations TO faultline_api;
GRANT UPDATE(config,config_hash,secret_id,credential_hint,revision,capabilities,probe_binding_hash,repository_id,disconnected,updated_at) ON faultline.source_connections TO faultline_api;
GRANT UPDATE(fence,status,value,import_id,error_code,updated_at) ON faultline.integration_captures TO faultline_api;
GRANT UPDATE(profile_hash,capabilities,probe_binding_hash,revision,deleted,updated_at) ON faultline.model_profiles TO faultline_api;
GRANT UPDATE(calls_reserved,calls_spent,input_reserved,input_spent,output_reserved,output_spent) ON faultline.model_budgets TO faultline_api;
GRANT UPDATE(status,reported_input,reported_output,response_hash,error_code,finished_at) ON faultline.model_calls TO faultline_api;
GRANT UPDATE(status,attempt,fence,lease_until,result,error_code,updated_at) ON faultline.provider_operations TO faultline_api;
